# GENERATED by bench.wstc.build_workflow_file from deploy/wstc/template_workflow.py.
# Do not edit the generated file: edit the workflow, the cases, the blocks or this template, and rebuild.
#
# One workflow (a recipe), compiled for a set of fires. Every asset is partitioned by fire,
# so one Dagster run of __ME___<workflow>_job on one fire (partition) does all of it:
#   __ME__/__WF__/<slot>/<step>     one per input step: LANDFIRE, roads override, wind, ...
#   __ME__/__WF__/reference/<block> the fire's observed perimeter, rasterized onto its grid
#   __ME__/__WF__/prediction        the model run
#   __ME__/__WF__/score/<metric>    the prediction vs the reference
# and __ME__/__WF__/report (not partitioned) is the workflow's table: one row per fire.
#
# How a step runs: its pod starts from its block's image (IMAGES), writes the blocks' code
# (CODE) to /tmp, runs the block, checks what it wrote against the conventions, and only then
# moves the artifact into place under its identity on the shared volume. A step whose identity
# already holds a finished artifact reuses it. A fire that lacks what a block needs (no NGFS
# detection, no station in range) gets an "unavailable" artifact with the reason, and every
# step after it for that fire says so too, instead of failing.
#
# This file only imports dagster and the standard library: the code server that loads it
# runs the server's standard image, without the blocks' packages.
import base64
import json
import os
import shutil
import subprocess
import sys
import time
from pathlib import Path

import dagster as dg

ME = "__ME__"
WF = "__WF__"
IMAGES = __IMAGES__              # {image family: image reference}
PLAN = json.loads(__PLAN__)      # bench.wstc.compile_plan(...)
CODE = __CODE__                  # {file name: source} of the blocks used + conventions + previews

# TEMP(shared-volume): the artifact store. Kai: not backed up, 10 GiB shared by everyone;
# finished artifacts move to the S3 bucket (wstc-dagster) next, under the same identity paths.
ART = Path(f"/opt/dagster/shared/storage/{ME}/bench/artifacts")
CODE_DIR = Path("/tmp/bench/code")
GROUP = f"{ME}_{WF}"
FIRES = dg.StaticPartitionsDefinition(sorted(PLAN["fires"]))
TAG_EMAIL = "bench/lfps_email"   # run tag carrying the email LANDFIRE's service requires
UNAVAILABLE_EXIT = 3             # a block's exit code for "this fire doesn't have what I need"


def _pod(image_family: str, resources: dict) -> dict:
    """op_tags for a step: start its pod from its block's image, with its block's resources
    (Kubernetes requests/limits, from the manifest; bench.wstc.k8s_resources)."""
    return {"dagster-k8s/config": {"container_config": {"image": IMAGES[image_family],
                                                        "resources": resources}}}


# --------------------------------------------------------------------------- #
# running code inside the step's pod
# --------------------------------------------------------------------------- #
def _python_env(extra: dict | None = None) -> dict:
    """Environment for block subprocesses: the shipped code on the path, the artifact root."""
    CODE_DIR.mkdir(parents=True, exist_ok=True)
    for name, text in CODE.items():
        (CODE_DIR / name).write_text(text)
    return {**os.environ, "PYTHONPATH": str(CODE_DIR), "BENCH_ARTIFACT_ROOT": str(ART),
            "MPLCONFIGDIR": "/tmp/bench/mpl", "PYTHONUNBUFFERED": "1", **(extra or {})}


class _Unavailable(Exception):
    pass


def _run(context, script: str, *args, extra_env: dict | None = None) -> None:
    """Run one of the shipped scripts with the image's block Python, streaming its output to
    the Dagster log. Exit code 3 means "unavailable" (raised as _Unavailable, with the
    block's reason); any other non-zero exit fails the step with the last lines attached.

    An image whose blocks need a different Python than Dagster's sets BENCH_PYTHON
    (bench-elmfire: Dagster on 3.10, pyretechnics on 3.12); otherwise it is Dagster's own."""
    t = time.time()
    python = os.environ.get("BENCH_PYTHON", sys.executable)
    proc = subprocess.Popen([python, str(CODE_DIR / script), *map(str, args)],
                            stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True,
                            env=_python_env(extra_env))
    tail = []
    for line in proc.stdout:
        line = line.rstrip()
        tail = (tail + [line])[-60:]
        if line and not line.startswith((" ", "{", "}", "]", "[")):     # skip pretty-printed JSON
            context.log.info(f"[{Path(script).stem}] {line[:400]}")
    code = proc.wait()
    if code == UNAVAILABLE_EXIT:
        reason = next((l[len("unavailable: "):] for l in reversed(tail) if l.startswith("unavailable: ")), "unavailable")
        raise _Unavailable(reason)
    if code != 0:
        raise dg.Failure(f"{script} failed after {time.time() - t:.0f}s", metadata={"output": "\n".join(tail)})


def _check_conventions(context, artifact: Path, case: dict) -> None:
    """Every raster a block wrote must follow docs/conventions.md (grid, orientation, CRS,
    units). Checked before the artifact is accepted, so no step ever reads a bad one."""
    case_file = artifact.parent / f"{artifact.name}.case.json"
    case_file.write_text(json.dumps(case))
    try:
        _run(context, "conventions.py", artifact, case_file)
    except dg.Failure as e:
        raise dg.Failure(f"{artifact.name}: breaks the conventions (docs/conventions.md)",
                         metadata=e.metadata) from None
    finally:
        case_file.unlink(missing_ok=True)


# --------------------------------------------------------------------------- #
# the artifact store: identity paths, reuse, atomic writes, unavailable markers
# --------------------------------------------------------------------------- #
def _done(path: str) -> dict | None:
    """The finished-marker of the artifact at `path` (its summary, or why it is unavailable,
    and who built it), if any."""
    marker = ART / path / "_done.json"
    return json.loads(marker.read_text()) if marker.exists() else None


def _materialize(context, path: str, case: dict, build) -> tuple[dict, bool]:
    """Build the artifact at its identity path unless it is already there.

    Returns (done marker, reused). `build(tmp)` writes into a temporary sibling; the result is
    checked and then renamed into place, so a reader never sees half an artifact and a failed
    step leaves nothing behind that looks finished. A build that raises _Unavailable leaves a
    marker saying why, which downstream steps read."""
    if done := _done(path):
        context.log.info(f"reused {path} (built {done.get('finished_utc')} by run {done.get('run_id', '?')[:8]})")
        return done, True
    final = ART / path
    tmp = ART / f"{path}.tmp-{context.run_id[:8]}"
    shutil.rmtree(tmp, ignore_errors=True)
    tmp.mkdir(parents=True)
    t = time.time()
    done = {"run_id": context.run_id, "finished_utc": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}
    try:
        done["summary"] = build(tmp) or {}
        _check_conventions(context, tmp, case)
    except _Unavailable as e:
        context.log.warning(f"unavailable for this fire: {e}")
        done.update(summary={}, unavailable=str(e))
    except BaseException:
        shutil.rmtree(tmp, ignore_errors=True)
        raise
    done["seconds"] = round(time.time() - t, 1)
    (tmp / "_done.json").write_text(json.dumps(done, default=str))
    if final.exists():                      # an unfinished leftover (no _done.json): replace it
        shutil.rmtree(final)
    os.replace(tmp, final)
    return done, False


def _upstream_unavailable(paths: dict) -> str | None:
    """Why this step can't run for this fire, if one of its inputs is unavailable."""
    for name, path in paths.items():
        d = _done(path)
        if d and d.get("unavailable"):
            # within a slot ("in") pass the reason on as is; across slots say which slot
            return d["unavailable"] if name == "in" else f"{name}: {d['unavailable']}"
    return None


def _run_step(context, script: str, step: dict, tmp: Path, extra_env: dict | None = None) -> dict:
    """Run a core block on its step.json (docs/block_contract.md) and return its summary."""
    step_file = tmp.parent / f"{tmp.name}.step.json"
    step_file.write_text(json.dumps({**step, "out_dir": str(tmp)}))
    try:
        _run(context, script, step_file, extra_env=extra_env)
    finally:
        step_file.unlink(missing_ok=True)
    return json.loads((tmp / "provenance.json").read_text()).get("summary", {})


def _meta(v):
    """A metadata value Dagster can show: numbers stay numbers (so they chart across fires),
    everything else becomes short text."""
    if isinstance(v, bool) or v is None:
        return str(v)
    if isinstance(v, (int, float)):
        return v
    return v if isinstance(v, str) and len(v) < 2000 else json.dumps(v, default=str)[:2000]


def _provenance(done: dict, reused: bool, path: str, identity: str) -> dict:
    """What every materialization records about where its artifact came from."""
    md = {**{k: _meta(v) for k, v in done.get("summary", {}).items()},
          "reused": reused, "artifact": path, "identity": identity,
          "built_by_run": done.get("run_id", "")[:8], "build_s": done.get("seconds")}
    if done.get("unavailable"):
        md["unavailable"] = done["unavailable"]
    return md


def _fire(context) -> dict:
    return PLAN["fires"][context.partition_key]


# --------------------------------------------------------------------------- #
# input steps and the reference
# --------------------------------------------------------------------------- #
def _input_asset(asset: dict):
    @dg.asset(key=dg.AssetKey(asset["key"]), group_name=GROUP, partitions_def=FIRES,
              deps=[dg.AssetKey(asset["after"])] if asset["after"] else [],
              description=f"{asset['block']} ({asset['kind']}): {asset['name']}"
                          + (f". Inserted because {asset['reason']}" if asset.get("reason") else ""),
              op_tags=_pod(asset["image"], asset["resources"]))
    def _a(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
        fire = _fire(context)
        st = fire["steps"][asset["name"]]

        def build(tmp: Path) -> dict:
            if why := _upstream_unavailable(st["input_paths"]):
                raise _Unavailable(why)
            step = {**st["payload"], "inputs": {k: str(ART / v) for k, v in st["input_paths"].items()}}
            email = context.run.tags.get(TAG_EMAIL, "")
            return _run_step(context, asset["code"], step, tmp, {"BENCH_LFPS_EMAIL": email} if email else None)
        done, reused = _materialize(context, st["path"], st["payload"]["case"], build)
        return dg.MaterializeResult(metadata=_provenance(done, reused, st["path"], st["identity"]))
    return _a


REF = PLAN["reference"]


@dg.asset(key=dg.AssetKey(REF["key"]), group_name=GROUP, partitions_def=FIRES,
          description="The fire's observed perimeter, rasterized onto its grid.",
          op_tags=_pod(REF["image"], REF["resources"]))
def reference(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    fire = _fire(context)
    ref = fire["reference"]
    text = PLAN["references"].get(context.partition_key)      # a local file shipped with the plan

    def build(tmp: Path) -> dict:
        inputs = {}
        if text is not None:
            src = tmp.parent / f"{tmp.name}.source.geojson"
            src.write_text(text)
            inputs["file"] = str(src)
        try:
            return _run_step(context, REF["code"], {**ref["payload"], "inputs": inputs}, tmp)
        finally:
            if inputs:
                Path(inputs["file"]).unlink(missing_ok=True)
    done, reused = _materialize(context, ref["path"], ref["payload"]["case"], build)
    return dg.MaterializeResult(metadata=_provenance(done, reused, ref["path"], ref["identity"]))


# --------------------------------------------------------------------------- #
# the model run, the scores, the report
# --------------------------------------------------------------------------- #
# the last step of every input slot: what the model depends on
TAILS = [a["key"] for a in PLAN["assets"] if not any(a["key"] == b["after"] for b in PLAN["assets"])]
PRED_KEY = dg.AssetKey([ME, WF, "prediction"])
MODEL = PLAN["model"]


def _preview_md(pred_dir: Path) -> str | None:
    png = pred_dir / "preview.png"
    if not png.exists():
        return None
    return f"![prediction preview](data:image/png;base64,{base64.b64encode(png.read_bytes()).decode()})"


@dg.asset(key=PRED_KEY, group_name=GROUP, partitions_def=FIRES, deps=[dg.AssetKey(k) for k in TAILS],
          description=f"{MODEL['block']} on this fire, params {json.dumps(MODEL['params'])}.",
          op_tags=_pod(MODEL["image"], MODEL["resources"]))
def prediction(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    fire = _fire(context)
    run = fire["run"]
    missing = [s for s, p in run["input_paths"].items() if not _done(p)]
    if missing:
        raise dg.Failure(f"inputs not built yet for slots {missing}")

    def build(tmp: Path) -> dict:
        if why := _upstream_unavailable(run["input_paths"]):
            raise _Unavailable(why)
        (tmp / "run.json").write_text(json.dumps(run["run_json"]))
        _run(context, MODEL["code"], tmp)
        pred = tmp / "prediction"
        # drawn by the framework, not the model, so every model's preview looks the same
        try:
            _run(context, "previews.py", pred, MODEL["params"].get("duration_min", 0) or 0)
        except dg.Failure as e:
            context.log.warning(f"preview failed (the prediction is kept): {e.metadata}")
        return json.loads((pred / "summary.json").read_text())

    done, reused = _materialize(context, run["path"], run["run_json"]["case"], build)
    md = _provenance(done, reused, run["path"], run["identity"])
    if preview := _preview_md(ART / run["path"] / "prediction"):
        md["preview"] = dg.MetadataValue.md(preview)
    return dg.MaterializeResult(metadata={**md, "model": MODEL["block"], "image": IMAGES[MODEL["image"]],
                                          "params": json.dumps(MODEL["params"])})


def _score_asset(metric: str):
    spec = PLAN["metrics"][metric]

    @dg.asset(key=dg.AssetKey([ME, WF, "score", metric]), group_name=GROUP, partitions_def=FIRES,
              deps=[PRED_KEY, dg.AssetKey(REF["key"])],
              description=f"{metric}: the prediction vs the observed perimeter.",
              op_tags=_pod(spec["image"], spec["resources"]))
    def _s(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
        fire = _fire(context)
        needs = {"prediction": fire["run"]["path"], "reference": fire["reference"]["path"]}
        missing = [n for n, p in needs.items() if not _done(p)]
        if missing:
            raise dg.Failure(f"not built yet: {missing}")

        def build(tmp: Path) -> dict:
            if why := _upstream_unavailable(needs):
                raise _Unavailable(why)
            step = {"block": metric, "kind": "metric", "case": fire["run"]["run_json"]["case"], "params": {},
                    "inputs": {"prediction": str(ART / needs["prediction"] / "prediction"),
                               "reference": str(ART / needs["reference"])}}
            _run_step(context, spec["code"], step, tmp)
            return json.loads((tmp / "score.json").read_text())
        path = fire["scores"][metric]
        done, reused = _materialize(context, path, fire["run"]["run_json"]["case"], build)
        return dg.MaterializeResult(metadata=_provenance(done, reused, path, path.rsplit("-", 1)[-1]))
    return _s


def _table_csv(rows: list[dict], cols: list[str]) -> str:
    import csv, io
    buf = io.StringIO()
    w = csv.DictWriter(buf, fieldnames=cols, extrasaction="ignore")
    w.writeheader()
    w.writerows(rows)
    return buf.getvalue()


@dg.asset(key=dg.AssetKey([ME, WF, "report"]), group_name=GROUP,
          deps=[dg.AssetKey([ME, WF, "score", m]) for m in PLAN["metrics"]],
          description="The workflow's table: one row per fire (reads the artifact store).")
def report(context: dg.AssetExecutionContext) -> dg.MaterializeResult:
    rows = []
    for name in sorted(PLAN["fires"]):
        fire = PLAN["fires"][name]
        pred = _done(fire["run"]["path"])
        row = {"fire": name, "status": "not run"}
        if pred:
            row["status"] = f"unavailable: {pred['unavailable']}" if pred.get("unavailable") else "done"
            row["predicted_ha"] = pred.get("summary", {}).get("burned_area_ha")
        for m in PLAN["metrics"]:
            s = _done(fire["scores"][m])
            if s and s.get("unavailable") and row["status"] == "done":
                row["status"] = f"not scored: {s['unavailable']}"
            elif s:
                row.update({k: v for k, v in s.get("summary", {}).items() if k in (m, "observed_ha", "scored_at_min")})
        rows.append(row)
    cols = list(dict.fromkeys(c for r in rows for c in r))
    table = "| " + " | ".join(cols) + " |\n|" + "---|" * len(cols) + "\n" + "\n".join(
        "| " + " | ".join(str(r.get(c, "")) for c in cols) + " |" for r in rows)
    md = {"fires": len(rows), "done": sum(r["status"] == "done" for r in rows),
          "table": dg.MetadataValue.md(table), "rows": dg.MetadataValue.json(rows)}
    # the same table as CSV, for comparing workflows offline: on the shared volume, and in S3
    csv_text = _table_csv(rows, cols)
    out = ART.parent / "tables" / f"{WF}.csv"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text(csv_text)
    md["csv"] = str(out)
    if os.environ.get("DAGSTER_S3_BUCKET"):
        try:
            import boto3
            s3, bucket, key = boto3.client("s3"), os.environ["DAGSTER_S3_BUCKET"], f"{ME}/bench/tables/{WF}.csv"
            s3.put_object(Bucket=bucket, Key=key, Body=csv_text.encode())
            md["csv_s3"] = f"s3://{bucket}/{key}"
            md["csv_download"] = dg.MetadataValue.url(s3.generate_presigned_url(
                "get_object", Params={"Bucket": bucket, "Key": key}, ExpiresIn=86400))
        except Exception as e:                     # the table is still in Dagster and on the volume
            context.log.warning(f"couldn't write the table to S3: {e}")
    return dg.MaterializeResult(metadata=md)


input_assets = [_input_asset(a) for a in PLAN["assets"]]
score_assets = [_score_asset(m) for m in PLAN["metrics"]]

defs = dg.Definitions(
    assets=[*input_assets, reference, prediction, *score_assets, report],
    jobs=[
        # one run per fire: launch with the tag dagster/partition=<fire>
        dg.define_asset_job(f"{ME}_{WF}_job",
                            selection=dg.AssetSelection.assets(*input_assets, reference, prediction, *score_assets)),
        dg.define_asset_job(f"{ME}_{WF}_report_job", selection=dg.AssetSelection.assets(report)),
    ],
)
